  btnText = "Hover Me",
  href = DEFAULT_HREF,
  className = "",
  bgColor = "#ff5f00",
  textColor = "#ffffff",
  fillBgColor = "#ffffff",
  fillTextColor = "#ff5f00",
  hoverFillBgColor = "#ffffff",
  hoverFillTextColor = "#ff5f00",
  arrowColor,
  hoverArrowColor,
  animationDuration = ANIMATION_DURATION_MS / 1000,
  fillOnHover = true,
